140  		// over its parent (prefix "a") for a path under the child,
141  		// independent of RepoPrefixes() iteration order.
142  		if strings.HasPrefix(rawPath, prefix+"/") && len(prefix) > len(best) {
143  			best = prefix
144  		}
145  	}
146  	return best
147  }
